// Handle both single contact and batch inputs
const input = $input.first().json;

let contacts = [];
if (Array.isArray(input.contacts)) {
    contacts = input.contacts;
} else if (Array.isArray(input)) {
    contacts = input;
} else if (input.email || input.name) {
    contacts = [input];
}

// Return as separate items for processing
return contacts.map(contact => ({
    json: {
        id: contact.id || null,
        name: contact.name || '',
        email: contact.email || '',
        company: contact.company || '',
        title: contact.title || '',
        linkedin_url: contact.linkedin_url || '',
        phone: contact.phone || '',
        location: contact.location || '',
        source: contact.source || 'manual',
        original_data: contact
    }
}));

