// Score contacts based on enrichment data
const items = $input.all();

return items.map(item => {
    const contact = item.json;
    let score = 0;
    const scoring_factors = [];

    // Title scoring
    const title = (contact.title || '').toLowerCase();
    if (title.includes('director') || title.includes('vp') || title.includes('chief')) {
        score += 30;
        scoring_factors.push('Senior leadership title');
    } else if (title.includes('manager') || title.includes('lead')) {
        score += 20;
        scoring_factors.push('Management title');
    } else if (title.includes('engineer') || title.includes('analyst')) {
        score += 10;
        scoring_factors.push('Technical role');
    }

    // Company relevance (if we have company intel)
    if (contact.company_intel?.is_target_company) {
        score += 25;
        scoring_factors.push('Target company');
    }

    // Clearance indicators
    const clearance = (contact.clearance || '').toLowerCase();
    if (clearance.includes('ts/sci')) {
        score += 20;
        scoring_factors.push('TS/SCI clearance');
    } else if (clearance.includes('secret')) {
        score += 10;
        scoring_factors.push('Secret clearance');
    }

    // Data completeness bonus
    if (contact.email && contact.phone) {
        score += 10;
        scoring_factors.push('Complete contact info');
    }
    if (contact.linkedin_url) {
        score += 5;
        scoring_factors.push('LinkedIn available');
    }

    // Location relevance
    const location = (contact.location || '').toLowerCase();
    const keyLocations = ['dc', 'washington', 'arlington', 'mclean', 'reston', 'san diego', 'huntsville'];
    if (keyLocations.some(loc => location.includes(loc))) {
        score += 15;
        scoring_factors.push('Key BD location');
    }

    return {
        json: {
            ...contact,
            bd_score: Math.min(score, 100),
            scoring_factors,
            is_high_priority: score >= 50,
            scored_at: new Date().toISOString()
        }
    };
});

const contacts = $input.all();
const highPriority = contacts
    .filter(c => c.json.is_high_priority)
    .map(c => c.json);

if (highPriority.length === 0) {
    // No high-priority contacts, still return something
    return [{
        json: {
            has_high_priority: false,
            total_processed: contacts.length,
            message: "No high-priority contacts in this batch"
        }
    }];
}

return [{
    json: {
        has_high_priority: true,
        total_processed: contacts.length,
        high_priority_count: highPriority.length,
        contacts: highPriority.slice(0, 10)  // Top 10 for notification
    }
}];

const data = $input.first().json;

const contactList = data.contacts
    .map(c => `• *${c.name}* (${c.company}) - Score: ${c.bd_score}`)
    .join('\n');

return [{
    json: {
        message: `🎯 *High-Priority Contacts Identified*\n\n` +
                 `Processed: ${data.total_processed} contacts\n` +
                 `High Priority: ${data.high_priority_count}\n\n` +
                 `*Top Contacts:*\n${contactList}`,
        data
    }
}];

const filterResult = $('Filter High Priority').first().json;
return [{
    json: {
        success: true,
        processed: filterResult.total_processed,
        high_priority_count: filterResult.high_priority_count || 0,
        timestamp: new Date().toISOString()
    }
}];
